# Figure 4 (formal): PRII association with immune transcriptomic modules
suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(tidyr);library(readr);library(patchwork);library(grid)})
set.seed(20261008)
args<-commandArgs(trailingOnly=FALSE); fa<-grep('^--file=',args,value=TRUE); script_dir<-if(length(fa)) dirname(normalizePath(sub('^--file=','',fa[1]))) else getwd(); root<-normalizePath(file.path(script_dir,'..'),mustWork=FALSE); out_dir<-script_dir
read_required<-function(p){if(!file.exists(p))stop('Missing input: ',p);read.csv(p,stringsAsFactors=FALSE,check.names=FALSE)}
mouse_cor<-read_required(file.path(root,'results/12wk_primary/immune/12wk_immune_psps_spearman.csv'))
mouse_scores<-read_required(file.path(root,'results/12wk_primary/immune/12wk_immune_sample_scores.csv'))
tcga<-read_required(file.path(root,'results/immune_validation/tcga_psps_immune_purity_adjusted.csv'))%>%filter(analysis=='purity_adjusted_partial_spearman')
gse<-read_required(file.path(root,'results/external_validation/GSE79668_PSPS_immune_correlations.csv'))
module_order<-c('immune_infiltration','leukocyte','t_cell','cytotoxic','b_cell','myeloid','macrophage_TAM','neutrophil','NK','inflammation_noncore')
module_labels<-c(immune_infiltration='Immune infiltration',leukocyte='Leukocyte',t_cell='T cell',cytotoxic='Cytotoxic',b_cell='B cell',myeloid='Myeloid',macrophage_TAM='Macrophage/TAM',neutrophil='Neutrophil',NK='NK cell',inflammation_noncore='Non-core inflammation')
theme_prii<-theme_bw(base_size=7,base_family='Arial')+theme(panel.grid.minor=element_blank(),panel.grid.major.y=element_blank(),panel.grid.major.x=element_line(linewidth=.2,colour='grey92'),axis.text=element_text(colour='grey25',size=6.2),axis.title=element_text(colour='grey15',size=6.5),axis.ticks=element_line(linewidth=.3,colour='grey40'),panel.border=element_rect(linewidth=.35,colour='grey30'),plot.tag=element_text(size=9,face='bold'),plot.tag.position=c(.01,.99),plot.margin=margin(3,3,3,3,unit='mm'))
fmt_q<-function(x)ifelse(is.na(x),'NA',ifelse(x<1e-3,formatC(x,format='e',digits=1),sprintf('%.3f',x)))
# a
mouse_cor<-mouse_cor%>%mutate(module_label=unname(module_labels[module]),module_label=factor(module_label,levels=rev(unname(module_labels[c('leukocyte','t_cell','cytotoxic','b_cell','myeloid','macrophage_TAM','neutrophil','NK','inflammation_noncore')]))),q_label=paste0('q=',fmt_q(padj_BH)))
g4a<-ggplot(mouse_cor,aes(spearman_rho,module_label))+geom_vline(xintercept=0,linetype='dashed',linewidth=.3,colour='grey55')+geom_segment(aes(x=0,xend=spearman_rho,yend=module_label),linewidth=1.2,colour='#542788',lineend='round')+geom_point(size=2.1,colour='#542788')+geom_text(aes(label=q_label),hjust=ifelse(mouse_cor$spearman_rho>=0,-.1,1.1),size=1.9,colour='grey25')+scale_x_continuous(limits=c(-.22,1.18),breaks=c(0,.25,.5,.75,1),expand=expansion(mult=c(.01,.02)))+labs(x='Spearman correlation with PRII',y=NULL,tag='a')+annotate('text',x=-.20,y=Inf,vjust=1.4,hjust=0,label='GSE292815 mouse pancreas; n=21',size=1.9,colour='grey35')+theme_prii
# b: representative mouse bulk associations; full heatmap exported as candidate
clean_group<-function(x)gsub('_','-',sub('_12wk$','',as.character(x)))
grp_levels<-c('CD','Safflower','HO-Safflower','Sunflower','HO-Sunflower')
group_cols<-c('CD'='#999999','Safflower'='#D6604D','HO-Safflower'='#B2182B','Sunflower'='#92C5DE','HO-Sunflower'='#2166AC')
mouse_scores$group_clean<-factor(clean_group(mouse_scores$group),levels=grp_levels)
scatter_modules<-c('t_cell','myeloid','inflammation_noncore')
scatter_stats<-mouse_cor%>%filter(module%in%scatter_modules)%>%mutate(module=factor(module,levels=scatter_modules),module_label=factor(unname(module_labels[as.character(module)]),levels=c('T cell','Myeloid','Non-core inflammation')),stat_label=paste0('rho=',sprintf('%.2f',spearman_rho),'\nq=',fmt_q(padj_BH),'  n=',n))
scatter_long<-mouse_scores%>%select(sample,group_clean,PRII=PSPS_core,all_of(scatter_modules))%>%pivot_longer(cols=all_of(scatter_modules),names_to='module',values_to='module_score')%>%mutate(module=factor(module,levels=scatter_modules),module_label=factor(unname(module_labels[as.character(module)]),levels=c('T cell','Myeloid','Non-core inflammation')))
g4b<-ggplot(scatter_long,aes(PRII,module_score,colour=group_clean))+geom_smooth(method='lm',formula=y~x,se=FALSE,linewidth=.4,colour='grey45')+geom_point(size=1.55,alpha=.9)+geom_text(data=scatter_stats,aes(x=-Inf,y=Inf,label=stat_label),inherit.aes=FALSE,hjust=-.08,vjust=1.2,size=1.7,colour='grey25')+facet_wrap(~module_label,nrow=1,scales='free_y')+scale_colour_manual(values=group_cols,labels=c('CD','Saf','HO-Saf','Sun','HO-Sun'))+scale_x_continuous(breaks=c(-1,0,1))+labs(x='PRII',y='Module score',tag='b',colour='Diet')+theme_prii+theme(axis.text=element_text(size=4.5),axis.title=element_text(size=5.4),strip.text=element_text(size=5.3),legend.position='bottom',legend.title=element_blank(),legend.text=element_text(size=4.3),legend.key.width=unit(3.5,'mm'),legend.spacing.x=unit(1,'mm'),panel.spacing=unit(1.2,'mm'))
mod_mouse<-c('leukocyte','t_cell','cytotoxic','b_cell','myeloid','macrophage_TAM','neutrophil','NK','inflammation_noncore')
mouse_scores<-mouse_scores%>%arrange(group_clean,sample)
heat<-mouse_scores%>%select(sample,group_clean,all_of(mod_mouse))%>%pivot_longer(cols=all_of(mod_mouse),names_to='module',values_to='score')%>%mutate(module_label=factor(unname(module_labels[module]),levels=rev(unname(module_labels[mod_mouse]))),sample=factor(sample,levels=unique(mouse_scores$sample)))
heat_candidate<-ggplot(heat,aes(sample,module_label,fill=score))+geom_tile(colour='white',linewidth=.25)+scale_fill_gradient2(low='#3B4CC0',mid='white',high='#B40426',midpoint=0,name='Module score')+labs(x='Mouse sample (ordered by diet)',y=NULL)+theme_prii+theme(axis.text.x=element_text(angle=90,hjust=1,vjust=.5,size=4.5),axis.text.y=element_text(size=5.3),legend.position='right',legend.text=element_text(size=5),legend.title=element_text(size=5.5),panel.grid=element_blank())
# c/d
forest_data<-function(dat,rho_col,q_col,n_col,study)dat%>%transmute(module,rho=.data[[rho_col]],q=.data[[q_col]],n=.data[[n_col]],study=study,module_label=unname(module_labels[module]))%>%filter(is.finite(rho))
tcga_f<-forest_data(tcga,'rho','fdr','n','TCGA-PAAD'); tcga_f$module_label<-factor(tcga_f$module_label,levels=rev(unname(module_labels[unique(tcga_f$module)])))
gse_f<-forest_data(gse,'rho','FDR_BH','n','GSE79668'); gse_f$module_label<-factor(gse_f$module_label,levels=rev(unname(module_labels[unique(gse_f$module)])))
forest_plot<-function(dat,tag,subtitle,col,xlab='Purity-adjusted Spearman rho'){ggplot(dat,aes(rho,module_label))+geom_vline(xintercept=0,linetype='dashed',linewidth=.3,colour='grey55')+geom_segment(aes(x=0,xend=rho,yend=module_label),linewidth=1.15,colour=col,lineend='round')+geom_point(size=2,colour=col)+geom_text(aes(label=paste0('q=',fmt_q(q))),hjust=-.08,size=1.8,colour='grey25')+scale_x_continuous(limits=c(-.08,1.03),breaks=c(0,.25,.5,.75,1),expand=expansion(mult=c(.01,.03)))+labs(x=xlab,y=NULL,tag=tag)+annotate('text',x=-.06,y=Inf,vjust=1.4,hjust=0,label=subtitle,size=1.85,colour='grey35')+theme_prii}
g4c<-forest_plot(tcga_f,'c','TCGA-PAAD primary tumors; exact-barcode purity; n=149','#008837')
g4d<-forest_plot(gse_f,'d','Independent PAAD cohort; n=51','#D95F02','Spearman correlation with PRII')
fig4<-(g4a|g4b)/(g4c|g4d)+plot_layout(widths=c(.90,1.65),heights=c(1.13,1))
pdf_out<-file.path(out_dir,'Fig4_PRII.pdf');tiff_out<-file.path(out_dir,'Fig4_PRII.tiff');ggsave(pdf_out,fig4,width=180,height=180,units='mm',device=cairo_pdf);tiff(tiff_out,width=180,height=180,units='mm',res=600,compression='lzw',type='cairo');print(fig4);dev.off();ggsave(file.path(out_dir,'Fig4b_mouse_immune_module_heatmap_candidate.pdf'),heat_candidate,width=180,height=100,units='mm',device=cairo_pdf);tiff(file.path(out_dir,'Fig4b_mouse_immune_module_heatmap_candidate.tiff'),width=180,height=100,units='mm',res=600,compression='lzw',type='cairo');print(heat_candidate);dev.off()
write.csv(mouse_cor,file.path(out_dir,'Fig4_PRII_mouse_correlations.csv'),row.names=FALSE);write.csv(tcga_f,file.path(out_dir,'Fig4_PRII_TCGA_purity_adjusted.csv'),row.names=FALSE);write.csv(gse_f,file.path(out_dir,'Fig4_PRII_GSE79668_replication.csv'),row.names=FALSE);write.csv(data.frame(cohort=c('GSE292815_12wk_mouse','TCGA-PAAD','GSE79668'),n=c(21,unique(tcga_f$n)[1],unique(gse_f$n)[1])),file.path(out_dir,'Fig4_PRII_sample_counts.csv'),row.names=FALSE)
cat('Wrote ',pdf_out,'\n',tiff_out,'\n',sep='')
